// Package postgres implements the trips storage ports with the queries in
// queries.sql (generated by sqlc into sqlcgen/).
package postgres

import (
	"context"
	"errors"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/shopspring/decimal"

	"github.com/AtmosferaSoltec/atm-km-api/internal/modules/trips/adapters/postgres/sqlcgen"
	"github.com/AtmosferaSoltec/atm-km-api/internal/modules/trips/app"
	"github.com/AtmosferaSoltec/atm-km-api/internal/modules/trips/domain"
	"github.com/AtmosferaSoltec/atm-km-api/internal/platform/tx"
)

const (
	uniqueViolation = "23505"
	// The partial unique index that keeps the car from being lent twice.
	oneInProgressIndex = "trips_one_in_progress_per_user"
)

// DB gives the ongoing transaction's connection, or the pool (tx.Runner).
type DB interface {
	DB(ctx context.Context) tx.DBTX
}

// Trips implements app.Repository.
type Trips struct {
	db DB
}

// NewTrips creates the trips repository.
func NewTrips(db DB) Trips { return Trips{db: db} }

func (r Trips) q(ctx context.Context) *sqlcgen.Queries { return sqlcgen.New(r.db.DB(ctx)) }

// Insert stores a new trip.
func (r Trips) Insert(ctx context.Context, trip domain.Trip) error {
	params := sqlcgen.InsertTripParams{
		ID: trip.ID, UserID: trip.UserID, Status: string(trip.Status),
		StartDate: trip.StartDate, StartKm: trip.StartKm, CreatedAt: trip.CreatedAt,
	}
	if ret := trip.Return; ret != nil {
		fuel := string(ret.FuelType)
		params.ReturnDate = &ret.Date
		params.EndKm = &ret.EndKm
		params.FuelType = &fuel
		params.FuelRate = &ret.Billing.FuelRate
		params.WearRate = &ret.Billing.WearRate
		params.FuelAmount = &ret.Billing.FuelAmount
		params.WearAmount = &ret.Billing.WearAmount
		params.TotalAmount = &ret.Billing.Total
	}
	err := r.q(ctx).InsertTrip(ctx, params)
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) && pgErr.Code == uniqueViolation && pgErr.ConstraintName == oneInProgressIndex {
		return domain.ErrAlreadyLent
	}
	return err
}

// Get finds one of the user's trips.
func (r Trips) Get(ctx context.Context, userID, id uuid.UUID) (domain.Trip, error) {
	return one(r.q(ctx).GetTrip(ctx, sqlcgen.GetTripParams{ID: id, UserID: userID}))
}

// Lock finds one of the user's trips and locks it until the transaction ends.
func (r Trips) Lock(ctx context.Context, userID, id uuid.UUID) (domain.Trip, error) {
	return one(r.q(ctx).LockTrip(ctx, sqlcgen.LockTripParams{ID: id, UserID: userID}))
}

// Open finds the trip in progress, if any.
func (r Trips) Open(ctx context.Context, userID uuid.UUID) (*domain.Trip, error) {
	trip, err := one(r.q(ctx).GetOpenTrip(ctx, userID))
	if errors.Is(err, domain.ErrNotFound) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	return &trip, nil
}

// List returns a page of the history and how many trips match in total.
func (r Trips) List(ctx context.Context, userID uuid.UUID, status *domain.Status, limit, offset int) ([]domain.Trip, int64, error) {
	var filter *string
	if status != nil {
		text := string(*status)
		filter = &text
	}
	q := r.q(ctx)
	rows, err := q.ListTrips(ctx, sqlcgen.ListTripsParams{
		UserID: userID, Status: filter, RowLimit: int32(limit), RowOffset: int32(offset), //nolint:gosec // bounded by the handler
	})
	if err != nil {
		return nil, 0, err
	}
	total, err := q.CountTrips(ctx, sqlcgen.CountTripsParams{UserID: userID, Status: filter})
	if err != nil {
		return nil, 0, err
	}
	return many(rows), total, nil
}

// ByStatus returns the newest trips with any of the statuses.
func (r Trips) ByStatus(ctx context.Context, userID uuid.UUID, statuses []domain.Status, limit int) ([]domain.Trip, error) {
	texts := make([]string, len(statuses))
	for i, status := range statuses {
		texts[i] = string(status)
	}
	rows, err := r.q(ctx).ListTripsByStatus(ctx, sqlcgen.ListTripsByStatusParams{
		UserID: userID, Statuses: texts, RowLimit: int32(limit), //nolint:gosec // bounded by the caller
	})
	return many(rows), err
}

// SaveReturn closes the trip with its billing.
func (r Trips) SaveReturn(ctx context.Context, userID, id uuid.UUID, ret domain.Return) error {
	fuel := string(ret.FuelType)
	return r.q(ctx).ReturnTrip(ctx, sqlcgen.ReturnTripParams{
		ID: id, UserID: userID, ReturnDate: &ret.Date, EndKm: &ret.EndKm, FuelType: &fuel,
		FuelRate: &ret.Billing.FuelRate, WearRate: &ret.Billing.WearRate,
		FuelAmount: &ret.Billing.FuelAmount, WearAmount: &ret.Billing.WearAmount, TotalAmount: &ret.Billing.Total,
	})
}

// SetStatus moves the trip to status.
func (r Trips) SetStatus(ctx context.Context, userID, id uuid.UUID, status domain.Status, paidDate *time.Time) error {
	return r.q(ctx).SetTripStatus(ctx, sqlcgen.SetTripStatusParams{ID: id, UserID: userID, Status: string(status), PaidDate: paidDate})
}

// Pay marks the pending trips among ids paid.
func (r Trips) Pay(ctx context.Context, userID uuid.UUID, ids []uuid.UUID, paidDate time.Time) ([]uuid.UUID, error) {
	return r.q(ctx).PayTrips(ctx, sqlcgen.PayTripsParams{UserID: userID, PaidDate: &paidDate, Ids: ids})
}

// Delete removes the trip; its photos' rows go with it.
func (r Trips) Delete(ctx context.Context, userID, id uuid.UUID) error {
	return r.q(ctx).DeleteTrip(ctx, sqlcgen.DeleteTripParams{ID: id, UserID: userID})
}

// BillableSince adds up the billable trips that started since a date.
func (r Trips) BillableSince(ctx context.Context, userID uuid.UUID, since time.Time) (app.Totals, error) {
	row, err := r.q(ctx).BillableSince(ctx, sqlcgen.BillableSinceParams{UserID: userID, StartDate: since})
	return app.Totals{DistanceKm: row.DistanceKm, Charged: row.Charged, Trips: row.Trips}, err
}

// FuelChargedByMonth is the fuel charged per month since a date.
func (r Trips) FuelChargedByMonth(ctx context.Context, userID uuid.UUID, since time.Time) ([]app.MonthAmount, error) {
	rows, err := r.q(ctx).FuelChargedByMonth(ctx, sqlcgen.FuelChargedByMonthParams{UserID: userID, StartDate: since})
	if err != nil {
		return nil, err
	}
	months := make([]app.MonthAmount, len(rows))
	for i, row := range rows {
		months[i] = app.MonthAmount{Month: row.Month, Amount: row.Charged}
	}
	return months, nil
}

// MaxOdometer is the highest reading any trip registered.
func (r Trips) MaxOdometer(ctx context.Context, userID uuid.UUID) (decimal.Decimal, error) {
	return r.q(ctx).MaxTripOdometer(ctx, userID)
}

// LastFuelType is the fuel type of the newest returned trip.
func (r Trips) LastFuelType(ctx context.Context, userID uuid.UUID) (*domain.FuelType, error) {
	text, err := r.q(ctx).LastFuelType(ctx, userID)
	if errors.Is(err, pgx.ErrNoRows) || (err == nil && text == nil) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	fuel := domain.FuelType(*text)
	return &fuel, nil
}

func one(row sqlcgen.Trip, err error) (domain.Trip, error) {
	if errors.Is(err, pgx.ErrNoRows) {
		return domain.Trip{}, domain.ErrNotFound
	}
	if err != nil {
		return domain.Trip{}, err
	}
	return toTrip(row), nil
}

func many(rows []sqlcgen.Trip) []domain.Trip {
	trips := make([]domain.Trip, len(rows))
	for i, row := range rows {
		trips[i] = toTrip(row)
	}
	return trips
}

func toTrip(row sqlcgen.Trip) domain.Trip {
	trip := domain.Trip{
		ID: row.ID, UserID: row.UserID, Status: domain.Status(row.Status),
		StartDate: row.StartDate, StartKm: row.StartKm, PaidDate: row.PaidDate, CreatedAt: row.CreatedAt,
	}
	// The table's checks guarantee a returned trip has every field.
	if row.ReturnDate != nil && row.EndKm != nil && row.FuelType != nil && row.FuelRate != nil &&
		row.WearRate != nil && row.FuelAmount != nil && row.WearAmount != nil && row.TotalAmount != nil {
		trip.Return = &domain.Return{
			Date: *row.ReturnDate, EndKm: *row.EndKm, FuelType: domain.FuelType(*row.FuelType),
			Billing: domain.Billing{
				FuelRate: *row.FuelRate, WearRate: *row.WearRate,
				FuelAmount: *row.FuelAmount, WearAmount: *row.WearAmount, Total: *row.TotalAmount,
			},
		}
	}
	return trip
}

// Photos implements app.Photos.
type Photos struct {
	db DB
}

// NewPhotos creates the photos repository.
func NewPhotos(db DB) Photos { return Photos{db: db} }

func (r Photos) q(ctx context.Context) *sqlcgen.Queries { return sqlcgen.New(r.db.DB(ctx)) }

// OfTrips returns the photos of several trips, by trip and leg.
func (r Photos) OfTrips(ctx context.Context, tripIDs []uuid.UUID) (map[uuid.UUID]map[domain.Leg]domain.Photo, error) {
	rows, err := r.q(ctx).PhotosOfTrips(ctx, tripIDs)
	if err != nil {
		return nil, err
	}
	photos := make(map[uuid.UUID]map[domain.Leg]domain.Photo)
	for _, row := range rows {
		photo := toPhoto(row)
		if photos[photo.TripID] == nil {
			photos[photo.TripID] = make(map[domain.Leg]domain.Photo, 2)
		}
		photos[photo.TripID][photo.Leg] = photo
	}
	return photos, nil
}

// Get finds a photo by id.
func (r Photos) Get(ctx context.Context, id uuid.UUID) (domain.Photo, error) {
	return onePhoto(r.q(ctx).GetPhoto(ctx, id))
}

// OfLeg finds a trip's photo for a leg.
func (r Photos) OfLeg(ctx context.Context, tripID uuid.UUID, leg domain.Leg) (domain.Photo, error) {
	return onePhoto(r.q(ctx).GetTripPhoto(ctx, sqlcgen.GetTripPhotoParams{TripID: tripID, Leg: string(leg)}))
}

// Insert stores a photo's metadata.
func (r Photos) Insert(ctx context.Context, photo domain.Photo) error {
	return r.q(ctx).InsertPhoto(ctx, sqlcgen.InsertPhotoParams{
		ID: photo.ID, TripID: photo.TripID, UserID: photo.UserID, Leg: string(photo.Leg),
		StorageKey: photo.StorageKey, ContentType: photo.ContentType,
		SizeBytes: int32(photo.SizeBytes), CreatedAt: photo.CreatedAt, //nolint:gosec // capped at MaxPhotoBytes
	})
}

// Delete removes a photo's metadata.
func (r Photos) Delete(ctx context.Context, id uuid.UUID) error {
	return r.q(ctx).DeleteTripPhoto(ctx, id)
}

// Expired returns photos created before a moment, oldest first.
func (r Photos) Expired(ctx context.Context, before time.Time, limit int) ([]domain.Photo, error) {
	rows, err := r.q(ctx).ExpiredPhotos(ctx, sqlcgen.ExpiredPhotosParams{CreatedAt: before, Limit: int32(limit)}) //nolint:gosec // small constant
	if err != nil {
		return nil, err
	}
	photos := make([]domain.Photo, len(rows))
	for i, row := range rows {
		photos[i] = toPhoto(row)
	}
	return photos, nil
}

func onePhoto(row sqlcgen.TripPhoto, err error) (domain.Photo, error) {
	if errors.Is(err, pgx.ErrNoRows) {
		return domain.Photo{}, domain.ErrNoPhoto
	}
	if err != nil {
		return domain.Photo{}, err
	}
	return toPhoto(row), nil
}

func toPhoto(row sqlcgen.TripPhoto) domain.Photo {
	return domain.Photo{
		ID: row.ID, TripID: row.TripID, UserID: row.UserID, Leg: domain.Leg(row.Leg),
		StorageKey: row.StorageKey, ContentType: row.ContentType,
		SizeBytes: int64(row.SizeBytes), CreatedAt: row.CreatedAt,
	}
}
